package controller.model.repository;
import java.util.List; import org.springframework.data.jpa.repository.JpaRepository;
public interface DonationRepository extends JpaRepository<Donation, Long> { List<Donation> findByUserIdOrderByDonationDateDesc(Long userId); long countByStatus(String status); List<Donation> findAllByOrderByDonationDateDesc(); boolean existsByAppointmentId(Long appointmentId); boolean existsByUserId(Long userId); boolean existsByUserIdAndDonationDate(Long userId,java.time.LocalDate donationDate); List<Donation> findByUserIdAndStatusIgnoreCaseOrderByDonationDateDesc(Long userId,String status); @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select d from Donation d where d.id = :id") java.util.Optional<Donation> findByIdForUpdate(@org.springframework.data.repository.query.Param("id") Long id); }
